import{_ as t}from"./chunks/100.I7A0VXqr.js";import{_ as a,o,c as r,ak as n}from"./chunks/framework.DC-k2h36.js";const i="/projects/esp32Sensor/en/latest/assets/1.C5on3FR5.webp",s="/projects/esp32Sensor/en/latest/assets/2.BZGpl5h7.webp",l="/projects/esp32Sensor/en/latest/assets/3.D68OjZSe.webp",d="/projects/esp32Sensor/en/latest/assets/4.zWwCW--x.webp",y=JSON.parse('{"title":"17. Fan Module","description":"","frontmatter":{},"headers":[],"relativePath":"docs/17. Fan Module.md","filePath":"docs/17. Fan Module.md"}'),c={name:"docs/17. Fan Module.md"};function p(h,e,m,u,g,_){return o(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="_17-fan-module" tabindex="-1">17. Fan Module <a class="header-anchor" href="#_17-fan-module" aria-label="Permalink to &quot;17. Fan Module&quot;">​</a></h1><h2 id="_17-1-introduction" tabindex="-1">17.1 Introduction <a class="header-anchor" href="#_17-1-introduction" aria-label="Permalink to &quot;17.1 Introduction&quot;">​</a></h2><p>The fan module runs with adjustable speed control and needs no extra motor driver board. Pairing it with a temperature and humidity sensor creates a smart fan that automatically adjusts its speed based on room temperature.</p><img loading="lazy" height="1865" width="2080" src="'+i+'" class="common_img" style="width:300px;"><h2 id="_17-2-technical-specifications" tabindex="-1">17.2 Technical Specifications <a class="header-anchor" href="#_17-2-technical-specifications" aria-label="Permalink to &quot;17.2 Technical Specifications&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Parameter</th><th style="text-align:center;">Description</th></tr></thead><tbody><tr><td style="text-align:center;">Operating voltage</td><td style="text-align:center;">5 V</td></tr><tr><td style="text-align:center;">Connector model</td><td style="text-align:center;">5264-4AW</td></tr><tr><td style="text-align:center;">Mounting compatibility</td><td style="text-align:center;">LEGO-compatible hole spacing</td></tr><tr><td style="text-align:center;">Dimensions</td><td style="text-align:center;">65.0 × 42.0 × 25.0 mm</td></tr></tbody></table><h2 id="_17-3-hands-on-project" tabindex="-1">17.3 Hands-On Project <a class="header-anchor" href="#_17-3-hands-on-project" aria-label="Permalink to &quot;17.3 Hands-On Project&quot;">​</a></h2><h3 id="_17-3-1-project-overview" tabindex="-1">17.3.1 Project Overview <a class="header-anchor" href="#_17-3-1-project-overview" aria-label="Permalink to &quot;17.3.1 Project Overview&quot;">​</a></h3><p>This project programs the fan module to spin at speed 60 for 10 s, stop for 5 s, and repeat this cycle continuously. It teaches how to set fan speeds and manage start-stop routines in code.</p><h3 id="_17-3-2-hardware-wiring" tabindex="-1">17.3.2 Hardware Wiring <a class="header-anchor" href="#_17-3-2-hardware-wiring" aria-label="Permalink to &quot;17.3.2 Hardware Wiring&quot;">​</a></h3><ul><li>Connect the fan module to port <strong>P5</strong> of the controller using a 4-pin module cable.</li></ul><img loading="lazy" height="588" width="810" src="'+s+'" class="common_img" style="width:400px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><ul><li><p><strong>This module supports connection to any port among P5, P6, P7, or P8 on the controller. Ensure that the port configured in the program matches the physical wiring.</strong></p></li><li><p><strong>Connecting to port P5 or P8 on the controller is recommended to prevent the fan from spinning immediately upon power-on due to hardware characteristics.</strong></p></li></ul></div><h3 id="_17-3-3-adding-extensions" tabindex="-1">17.3.3 Adding Extensions <a class="header-anchor" href="#_17-3-3-adding-extensions" aria-label="Permalink to &quot;17.3.3 Adding Extensions&quot;">​</a></h3><ul><li>Select <strong>Fan module(Black)</strong> under the <strong>Output module</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+l+'" class="common_img" style="width:800px;"><h3 id="_17-3-4-complete-program-and-analysis" tabindex="-1">17.3.4 Complete Program and Analysis <a class="header-anchor" href="#_17-3-4-complete-program-and-analysis" aria-label="Permalink to &quot;17.3.4 Complete Program and Analysis&quot;">​</a></h3><ol><li><p>Inside the main program loop, fan speed settings and delay routines execute sequentially:</p><ul><li><p>Set the fan on port P5 to a speed of 60, then wait 10 s.</p></li><li><p>Set the fan on port P5 to a speed of 0, then wait 5 s.</p></li></ul></li><li><p>The program repeats this entire start-stop cycle continuously.</p></li></ol><img loading="lazy" height="440" width="534" src="'+d+'" class="common_img" style="width:500px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The source files are available for download under <a href="https://drive.google.com/drive/folders/1TXgifpt9LbPfn2A8MxY_fA1Vpq4xoemE?usp=sharing" target="_blank" rel="noreferrer">Program Files/17 Fan Module.sb3</a>.</strong></p></div><h3 id="_17-3-5-program-upload" tabindex="-1">17.3.5 Program Upload <a class="header-anchor" href="#_17-3-5-program-upload" aria-label="Permalink to &quot;17.3.5 Program Upload&quot;">​</a></h3><ul><li>Click <strong>Connect device</strong>, select the serial port, then click the upload button. Wait for the upload success notification to complete the program transfer.</li></ul><img loading="lazy" height="360" width="640" src="'+t+'" class="common_img" style="width:800px;"><h3 id="_17-3-6-program-outcome" tabindex="-1">17.3.6 Program Outcome <a class="header-anchor" href="#_17-3-6-program-outcome" aria-label="Permalink to &quot;17.3.6 Program Outcome&quot;">​</a></h3><p>Once the program upload is complete, the fan module runs continuously in a loop. It spins at speed 60 for 10 s and stops for 5 s, repeating the cycle to demonstrate adjustable speed and periodic motion.</p>',25)])])}const x=a(c,[["render",p]]);export{y as __pageData,x as default};
